import keras


def build_vertical_tower() -> keras.Model:
    """Generated by NTB from vertical-tower. Do not edit by hand."""
    x = keras.Input(batch_shape=(None, 256), dtype="float32", name="x")
    stack_0_fc = keras.layers.Dense(units=256, use_bias=True)(x)
    stack_0_act = keras.activations.relu(stack_0_fc)
    stack_1_fc = keras.layers.Dense(units=256, use_bias=True)(stack_0_act)
    stack_1_act = keras.activations.relu(stack_1_fc)
    stack_2_fc = keras.layers.Dense(units=256, use_bias=True)(stack_1_act)
    stack_2_act = keras.activations.relu(stack_2_fc)
    stack_3_fc = keras.layers.Dense(units=256, use_bias=True)(stack_2_act)
    stack_3_act = keras.activations.relu(stack_3_fc)
    stack_4_fc = keras.layers.Dense(units=256, use_bias=True)(stack_3_act)
    stack_4_act = keras.activations.relu(stack_4_fc)
    stack_5_fc = keras.layers.Dense(units=256, use_bias=True)(stack_4_act)
    stack_5_act = keras.activations.relu(stack_5_fc)
    stack_6_fc = keras.layers.Dense(units=256, use_bias=True)(stack_5_act)
    stack_6_act = keras.activations.relu(stack_6_fc)
    stack_7_fc = keras.layers.Dense(units=256, use_bias=True)(stack_6_act)
    stack_7_act = keras.activations.relu(stack_7_fc)
    stack_8_fc = keras.layers.Dense(units=256, use_bias=True)(stack_7_act)
    stack_8_act = keras.activations.relu(stack_8_fc)
    stack_9_fc = keras.layers.Dense(units=256, use_bias=True)(stack_8_act)
    stack_9_act = keras.activations.relu(stack_9_fc)
    stack_10_fc = keras.layers.Dense(units=256, use_bias=True)(stack_9_act)
    stack_10_act = keras.activations.relu(stack_10_fc)
    stack_11_fc = keras.layers.Dense(units=256, use_bias=True)(stack_10_act)
    stack_11_act = keras.activations.relu(stack_11_fc)
    return keras.Model(inputs=x, outputs=stack_11_act, name="vertical_tower")
